sys_script_include.script:
var MediaUtilsPerformance = Class.create();
MediaUtilsPerformance.prototype = {
    initialize: function() {},
    refQualMedias: function() {
        var moviesNoToBeShown = [];
        var grReview = new GlideRecord("x_1330572_sharkf_0_review");
        grReview.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4");
        grReview.query();

		while (grReview.next()) {
            moviesNoToBeShown.push(grReview.media.sys_id.toString());
        };

		var moviesToBeShown = [];
        var grMedia = new GlideRecord("x_1330572_sharkf_0_media");
        grMedia.addQuery("state", "3");
        grMedia.query();

		while (grMedia.next()) {
            if (moviesNoToBeShown.indexOf(grMedia.getUniqueValue()) == -1) {
                moviesToBeShown.push(grMedia.getUniqueValue());
            };
        };

		return "sys_idIN" + moviesToBeShown.join(",");
    },

    type: 'MediaUtilsPerformance'
};
